head.script:
scwin.screenId = "jldbnf00100";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    /* sdd-asis-lifecycle:begin initPageIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_searchNoticeListByCondReq').set('pageIndex', "1");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $('#paging7 table:first-child').attr('align', 'center');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00100.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 3개다(notice#searchnoticelist vs notice#searchnoticespec vs notice#downloadfile) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf00100.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.ipt_srchWord_onkeydown
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_srchWord_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_srchWord_onkeydown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(event.keyCode==13){replacePercent(selfVar);await scwin.searchNoticeListByCond();}
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00100.ipt_srchWord_onkeydown' }); }
};

/**
 * @event
 * @name scwin.ipt_srchWord_onblur
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_srchWord_onblur = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_srchWord_onblur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        replacePercent(selfVar);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00100.ipt_srchWord_onblur' }); }
};

/**
 * @event
 * @name scwin.btn_searchNoticeListByCond_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_searchNoticeListByCond_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_searchNoticeListByCond_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.searchNoticeListByCond()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00100.btn_searchNoticeListByCond_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_result_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["attachFileNm"] !== '') { if (typeof scwin.fileDown === 'function') { await scwin.fileDown(r["contnId"], r["attachFileNm"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fileDown (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fileDown'); } return; }
        if (typeof scwin.searchNoticeSpec === 'function') { await scwin.searchNoticeSpec(r["contnId"]); } else { console.error('[sdd] 행 동작 미정의: scwin.searchNoticeSpec (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchNoticeSpec'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.span_52_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.span_52_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin span_52_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00100.span_52_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_searchNoticeListByCond
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchNoticeListByCond = async function () {
    const sbmOptions = {
        id: "tx_fn_searchNoticeListByCond",
        method: "post",
        action: "/main/notice.do?method=searchNoticeList",
        ref: "dma_searchNoticeListByCondReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf00100.tx_fn_searchNoticeListByCond" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_searchNoticeSpec
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchNoticeSpec = async function () {
    const sbmOptions = {
        id: "tx_fn_searchNoticeSpec",
        method: "post",
        action: "/main/notice.do?method=searchNoticeSpec",
        ref: "dma_searchNoticeSpecReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf00100.tx_fn_searchNoticeSpec" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_fileDown = async function () {
    try { return await $c.data.downFile("/main/notice.do?method=downloadFile", "", ($c.util.getComponent("dma_fileDownReq") ? $c.util.getComponent("dma_fileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_result_fmt_attachFileNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_result_fmt_attachFileNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "attachFileNm") ?? '') : '');
        if (v !== '') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "첨부파일" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.attachFileNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.searchNoticeListByCond
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchNoticeListByCond = async function () {
    /* sdd-asis-lifecycle:begin fn_searchNoticeListByCond — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const width = 670;
    const height = 500;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    _previewWindow = $c.win.openPopup("/notice/notice.xml", { id: "popNoticeList", resizable: false, scrollbars: true, type: "pageFramePopup" }, ($c.util.getComponent("dma_searchNoticeListByCondReq") ? $c.util.getComponent("dma_searchNoticeListByCondReq").getJSON() : {}));
    const srchDiv = $("#srchDiv option:selected").val();
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent("dma_searchNoticeListByCondReq").set("srchDiv", srchDiv);
    fm.action = '/main/notice.do?method=searchNoticeList';

    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchNoticeSpec
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId
 * @returns
 * @hidden N
*/
scwin.searchNoticeSpec = async function (contnId) {
    /* sdd-asis-lifecycle:begin fn_searchNoticeSpec — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_searchNoticeListByCondReq').set('contnId', contnId);
    fm.action = '/main/notice.do?method=searchNoticeSpec';
    await scwin.tx_fn_searchNoticeSpec();
    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId attachFileNm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (contnId, attachFileNm) {
    /* sdd-asis-lifecycle:begin fn_fileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (attachFileNm == null || attachFileNm === "") {
        await $c.win.alert("첨부파일이 없습니다.");
        return;
    }
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_searchNoticeListByCondReq').set('contnId', contnId);
    fm.action = '/main/notice.do?method=downloadFile';
    await scwin.tx_fn_fileDown();
    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_48_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_48_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchNoticeListByCondReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_48.page' }); } scwin.searchNoticeListByCond(); };
